insert into public.questions (exam_category, subject, topic, type, difficulty, body, body_hi, question_data, options, marks_correct, marks_wrong, explanation, explanation_hi, concept_group_id, source_type, source_citation, status)
values
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','medium','Consider the following statements about national income aggregates:','राष्ट्रीय आय के समुच्चयों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["GDP at market prices equals GVA at basic prices plus product taxes minus product subsidies.", "GNP equals GDP plus net factor income from abroad.", "National income is the net national product at market prices."], "statements_hi": ["बाज़ार मूल्य पर GDP, आधार मूल्य पर GVA में उत्पाद कर जोड़ने और उत्पाद सब्सिडी घटाने के बराबर होता है।", "GNP, GDP में विदेशों से प्राप्त शुद्ध कारक आय जोड़ने के बराबर होता है।", "राष्ट्रीय आय बाज़ार मूल्य पर शुद्ध राष्ट्रीय उत्पाद है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Since the 2011-12 revision, India''s headline growth is measured by GDP at constant market prices, built up from gross value added at basic prices; adding net factor income from abroad -- what Indians earn abroad minus what foreigners earn in India -- gives GNP. Statement 3 is wrong: national income is NNP at factor cost -- net national product after removing indirect taxes and adding subsidies, so that it measures the incomes actually paid to the factors of production.','कथन 1 और 2 सही हैं। 2011-12 के संशोधन के बाद से भारत की मुख्य वृद्धि स्थिर बाज़ार मूल्य पर GDP से मापी जाती है, जो आधार मूल्य पर सकल मूल्य वर्धन से बनती है; इसमें विदेशों से शुद्ध कारक आय, यानी भारतीयों द्वारा विदेश में अर्जित आय में से विदेशियों द्वारा भारत में अर्जित आय घटाकर, जोड़ने से GNP मिलता है। कथन 3 गलत है: राष्ट्रीय आय साधन लागत पर NNP है, यानी अप्रत्यक्ष कर हटाकर और सब्सिडी जोड़कर प्राप्त शुद्ध राष्ट्रीय उत्पाद, ताकि यह उत्पादन के साधनों को वास्तव में दी गई आय को मापे।','econ-national-income-aggregates','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- National Income Accounting; Ministry of Statistics and Programme Implementation.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','medium','Consider the following statements about what is counted in GDP:','GDP में क्या गिना जाता है, इसके बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The sale of a second-hand car adds its full price to the GDP of the year of sale.", "Old-age pensions paid by the government are not counted in GDP.", "The unpaid household work of a homemaker is counted in GDP."], "statements_hi": ["पुरानी कार की बिक्री उसकी पूरी क़ीमत को बिक्री वाले वर्ष के GDP में जोड़ती है।", "सरकार द्वारा दी जाने वाली वृद्धावस्था पेंशन GDP में नहीं गिनी जाती।", "गृहिणी का बिना वेतन का घरेलू काम GDP में गिना जाता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: pensions, scholarships and unemployment benefits are transfer payments -- they are not payment for any current production, so they are left out of GDP. Statement 1 is wrong: the car was counted in the year it was made; only the dealer''s commission on the resale is a new service and enters GDP. Statement 3 is wrong: unpaid work within the household is outside the market and is not valued in GDP, one of the measure''s best-known limitations.','केवल कथन 2 सही है: पेंशन, छात्रवृत्ति और बेरोज़गारी भत्ते हस्तांतरण भुगतान हैं; ये किसी वर्तमान उत्पादन का भुगतान नहीं हैं, इसलिए GDP से बाहर रहते हैं। कथन 1 गलत है: कार उसी वर्ष गिनी जा चुकी है जिसमें वह बनी थी; पुनर्विक्रय पर केवल डीलर का कमीशन एक नई सेवा है और GDP में जुड़ता है। कथन 3 गलत है: घर के भीतर का बिना वेतन का काम बाज़ार से बाहर है और GDP में उसका मूल्य नहीं जोड़ा जाता; यह इस माप की सबसे प्रसिद्ध सीमाओं में से एक है।','econ-gdp-what-counts','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- National Income Accounting.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','medium','Consider the following statements about price indices in India:','भारत के मूल्य सूचकांकों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Wholesale Price Index does not cover services.", "The Consumer Price Index (Combined) is compiled by the National Statistics Office.", "The Consumer Price Index for Industrial Workers is compiled by the Labour Bureau.", "Food items carry a larger weight in the WPI than in the CPI (Combined)."], "statements_hi": ["थोक मूल्य सूचकांक (WPI) सेवाओं को शामिल नहीं करता।", "उपभोक्ता मूल्य सूचकांक (संयुक्त) राष्ट्रीय सांख्यिकी कार्यालय द्वारा संकलित किया जाता है।", "औद्योगिक श्रमिकों के लिए उपभोक्ता मूल्य सूचकांक (CPI-IW) श्रम ब्यूरो संकलित करता है।", "खाद्य वस्तुओं का भार CPI (संयुक्त) की तुलना में WPI में अधिक है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. The WPI, compiled by the Office of the Economic Adviser in the Department for Promotion of Industry and Internal Trade, tracks goods at the first point of bulk sale; the CPI, compiled by the NSO under the Ministry of Statistics, covers goods and services bought by households, which is why the RBI targets it; the Labour Bureau''s CPI-IW is used to revise dearness allowance. Statement 4 is wrong: food has close to half the weight in the CPI (Combined) of the 2012 series, but only about a quarter in the WPI, which gives large weights to manufactured products and fuel.','कथन 1, 2 और 3 सही हैं। उद्योग संवर्धन और आंतरिक व्यापार विभाग के आर्थिक सलाहकार कार्यालय द्वारा संकलित WPI वस्तुओं को थोक बिक्री के पहले बिंदु पर मापता है; सांख्यिकी मंत्रालय के अंतर्गत NSO द्वारा संकलित CPI परिवारों द्वारा ख़रीदी जाने वाली वस्तुओं और सेवाओं को शामिल करता है, इसीलिए RBI इसे लक्ष्य बनाता है; श्रम ब्यूरो का CPI-IW महँगाई भत्ते में संशोधन के लिए प्रयुक्त होता है। कथन 4 गलत है: 2012 श्रृंखला के CPI (संयुक्त) में भोजन का भार लगभग आधा है, पर WPI में केवल लगभग एक-चौथाई, जिसमें विनिर्मित उत्पादों और ईंधन को अधिक भार दिया जाता है।','econ-price-indices-wpi-cpi','original_pattern_matched','Ministry of Statistics and Programme Implementation; Office of the Economic Adviser, DPIIT.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','medium','Consider the following statements about inflation:','मुद्रास्फीति के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Demand-pull inflation arises when aggregate demand runs ahead of the economy''s capacity to supply.", "Cost-push inflation can be caused by a sharp rise in the price of crude oil.", "Disinflation means a fall in the rate of inflation while prices continue to rise."], "statements_hi": ["माँग-प्रेरित मुद्रास्फीति तब होती है जब समग्र माँग अर्थव्यवस्था की आपूर्ति क्षमता से आगे निकल जाती है।", "लागत-प्रेरित मुद्रास्फीति कच्चे तेल की क़ीमत में तेज़ वृद्धि से हो सकती है।", "अवस्फीति (disinflation) का अर्थ है मुद्रास्फीति की दर का घटना, जबकि क़ीमतें बढ़ती रहती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. Too much money chasing too few goods pulls prices up; a rise in the cost of an input used almost everywhere, such as oil or wages, pushes them up. Disinflation -- say from 7 to 4 per cent -- still means rising prices, only more slowly; deflation is an actual fall in the price level.','तीनों कथन सही हैं। बहुत अधिक मुद्रा का बहुत कम वस्तुओं के पीछे भागना क़ीमतों को ऊपर खींचता है; तेल या मज़दूरी जैसे लगभग हर जगह प्रयुक्त किसी आदान की लागत बढ़ना उन्हें ऊपर धकेलता है। अवस्फीति, मान लीजिए 7 से 4 प्रतिशत, का अर्थ अब भी बढ़ती क़ीमतें है, बस धीमी गति से; अपस्फीति (deflation) मूल्य स्तर का वास्तविक रूप से घटना है।','econ-inflation-types-disinflation','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics; Reserve Bank of India -- Monetary Policy Report.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','medium','Consider the following statements about the GDP deflator:','GDP अपस्फीतिकारक (deflator) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The GDP deflator includes the prices of imported goods.", "If nominal GDP grows by 10 per cent and the GDP deflator by 4 per cent, real GDP grows by about 6 per cent.", "The GDP deflator is published every month."], "statements_hi": ["GDP अपस्फीतिकारक में आयातित वस्तुओं की क़ीमतें शामिल होती हैं।", "यदि नाममात्र GDP 10 प्रतिशत और GDP अपस्फीतिकारक 4 प्रतिशत बढ़ें, तो वास्तविक GDP लगभग 6 प्रतिशत बढ़ती है।", "GDP अपस्फीतिकारक हर महीने प्रकाशित होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct: real growth is roughly nominal growth minus the rise in the deflator. Statement 1 is wrong: the deflator covers only goods and services produced within the country, so the prices of imports stay out -- unlike the CPI, which includes imported goods that households buy. Statement 3 is wrong: the deflator is the ratio of nominal to real GDP, so it is available only when GDP is estimated -- every quarter, not every month.','केवल कथन 2 सही है: वास्तविक वृद्धि मोटे तौर पर नाममात्र वृद्धि में से अपस्फीतिकारक की वृद्धि घटाने के बराबर होती है। कथन 1 गलत है: अपस्फीतिकारक केवल देश के भीतर उत्पादित वस्तुओं और सेवाओं को शामिल करता है, इसलिए आयात की क़ीमतें बाहर रहती हैं; CPI इससे भिन्न है, जिसमें परिवारों द्वारा ख़रीदी गई आयातित वस्तुएँ भी शामिल हैं। कथन 3 गलत है: अपस्फीतिकारक नाममात्र और वास्तविक GDP का अनुपात है, इसलिए यह तभी उपलब्ध होता है जब GDP का अनुमान लगता है, यानी हर तिमाही, हर महीने नहीं।','econ-gdp-deflator','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- National Income Accounting.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Inflation means a sustained rise in the general level of prices.", "Deflation means a general rise in prices."], "statements_hi": ["मुद्रास्फीति का अर्थ सामान्य मूल्य स्तर में लगातार वृद्धि है।", "अपस्फीति का अर्थ क़ीमतों में सामान्य वृद्धि है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: deflation is a sustained fall in the general price level, which can hurt an economy by making people put off spending and by raising the real burden of debt.','केवल कथन 1 सही है। कथन 2 गलत है: अपस्फीति सामान्य मूल्य स्तर में लगातार गिरावट है, जो लोगों को ख़र्च टालने के लिए प्रेरित करके और ऋण के वास्तविक बोझ को बढ़ाकर अर्थव्यवस्था को हानि पहुँचा सकती है।','econ-inflation-deflation-easy','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Banking is part of the secondary sector of the economy.", "Agriculture and mining are primary activities."], "statements_hi": ["बैंकिंग अर्थव्यवस्था के द्वितीयक क्षेत्र का भाग है।", "कृषि और खनन प्राथमिक क्रियाकलाप हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Statement 1 is wrong: banking, like trade, transport and communication, is a service and belongs to the tertiary sector; the secondary sector turns raw materials into goods, as in manufacturing and construction.','केवल कथन 2 सही है। कथन 1 गलत है: व्यापार, परिवहन और संचार की तरह बैंकिंग एक सेवा है और तृतीयक क्षेत्र का भाग है; द्वितीयक क्षेत्र कच्चे माल को वस्तुओं में बदलता है, जैसे विनिर्माण और निर्माण में।','econ-sectors-banking-easy','original_pattern_matched','NCERT Class X, Understanding Economic Development -- Sectors of the Indian Economy.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','hard','Consider the following statements about some macroeconomic relationships:','कुछ समष्टि-आर्थिक संबंधों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Phillips curve shows an inverse relationship between inflation and unemployment in the short run.", "In a liquidity trap, further cuts in interest rates do little to raise spending.", "The Laffer curve relates the rate of inflation to the level of output."], "statements_hi": ["फ़िलिप्स वक्र अल्पकाल में मुद्रास्फीति और बेरोज़गारी के बीच विपरीत संबंध दर्शाता है।", "तरलता जाल (liquidity trap) में ब्याज दरों में और कटौती से ख़र्च बहुत कम बढ़ता है।", "लैफ़र वक्र मुद्रास्फीति की दर को उत्पादन के स्तर से जोड़ता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. The Phillips curve trade-off tends to break down over longer periods, as the stagflation of the 1970s showed. In a liquidity trap, with rates already close to zero, people prefer to hold cash, so monetary easing loses force -- as Japan found in the 1990s. Statement 3 is wrong: the Laffer curve relates tax rates to tax revenue, suggesting that beyond a point higher rates can bring in less revenue.','कथन 1 और 2 सही हैं। फ़िलिप्स वक्र का यह समझौता (trade-off) लंबी अवधि में टूटने लगता है, जैसा 1970 के दशक की मुद्रास्फीतिजनित मंदी (stagflation) ने दिखाया। तरलता जाल में, जब दरें पहले ही शून्य के पास होती हैं, लोग नक़दी रखना पसंद करते हैं, इसलिए मौद्रिक ढील अपना असर खो देती है, जैसा जापान ने 1990 के दशक में अनुभव किया। कथन 3 गलत है: लैफ़र वक्र कर की दरों को कर राजस्व से जोड़ता है, और यह संकेत करता है कि एक सीमा के बाद ऊँची दरें कम राजस्व ला सकती हैं।','econ-phillips-liquidity-trap-laffer','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics; Reserve Bank of India -- Monetary Policy Report.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','statement_based','hard','Consider the following statements about measuring inflation:','मुद्रास्फीति मापने के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["A low price level in the same month of the previous year can make this year''s inflation rate look high even when prices are steady now.", "Core inflation is more volatile than headline inflation.", "Headline CPI inflation leaves out the prices of services."], "statements_hi": ["पिछले वर्ष के उसी महीने का निम्न मूल्य स्तर इस वर्ष की मुद्रास्फीति दर को ऊँचा दिखा सकता है, भले ही अभी क़ीमतें स्थिर हों।", "मूल (core) मुद्रास्फीति मुख्य (headline) मुद्रास्फीति से अधिक अस्थिर होती है।", "मुख्य CPI मुद्रास्फीति सेवाओं की क़ीमतों को शामिल नहीं करती।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: this is the base effect -- year-on-year inflation compares today''s index with last year''s, so an unusually low or high base distorts the rate. Statement 2 is wrong: core inflation strips out the most volatile items, food and fuel, precisely so that it is steadier and shows the underlying trend. Statement 3 is wrong: the CPI basket includes services such as housing, health, education, transport and communication; it is the WPI that covers goods alone.','केवल कथन 1 सही है: यह आधार प्रभाव (base effect) है; वर्ष-दर-वर्ष मुद्रास्फीति आज के सूचकांक की तुलना पिछले वर्ष से करती है, इसलिए असामान्य रूप से निम्न या ऊँचा आधार दर को विकृत कर देता है। कथन 2 गलत है: मूल मुद्रास्फीति सबसे अस्थिर वस्तुओं, भोजन और ईंधन, को हटा देती है, ठीक इसलिए कि वह अधिक स्थिर रहे और अंतर्निहित प्रवृत्ति दिखाए। कथन 3 गलत है: CPI की टोकरी में आवास, स्वास्थ्य, शिक्षा, परिवहन और संचार जैसी सेवाएँ शामिल हैं; केवल वस्तुओं को WPI शामिल करता है।','econ-base-effect-core-inflation','original_pattern_matched','Reserve Bank of India -- Monetary Policy Framework Agreement; Monetary Policy Report.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','mcq','medium','Which one of the following best describes ''stagflation''?','निम्नलिखित में से कौन-सा ''मुद्रास्फीतिजनित मंदी'' (stagflation) का सबसे अच्छा वर्णन करता है?','{}'::jsonb,'[{"id": "a", "body": "Falling prices combined with rising output and employment", "body_hi": "बढ़ते उत्पादन और रोज़गार के साथ गिरती क़ीमतें", "isCorrect": false}, {"id": "b", "body": "Rising prices combined with very rapid growth in output and jobs", "body_hi": "उत्पादन और रोज़गार में बहुत तेज़ वृद्धि के साथ बढ़ती क़ीमतें", "isCorrect": false}, {"id": "c", "body": "High inflation with stagnant output and high unemployment", "body_hi": "स्थिर उत्पादन और ऊँची बेरोज़गारी के साथ ऊँची मुद्रास्फीति", "isCorrect": true}, {"id": "d", "body": "A sudden rise in the external value of the currency", "body_hi": "मुद्रा के बाहरी मूल्य में अचानक वृद्धि", "isCorrect": false}]'::jsonb,2,0.66,'Stagflation -- stagnation plus inflation -- is the combination the simple Phillips curve said should not happen; it hit much of the world after the oil price shocks of the 1970s, when costlier oil raised prices while cutting output. It is hard to treat, because raising rates to curb inflation deepens the slump.','मुद्रास्फीतिजनित मंदी, यानी गतिहीनता और मुद्रास्फीति, वह मेल है जिसके बारे में सरल फ़िलिप्स वक्र कहता था कि ऐसा नहीं होना चाहिए; 1970 के दशक के तेल मूल्य झटकों के बाद यह विश्व के बड़े भाग में आया, जब महँगे तेल ने क़ीमतें बढ़ाईं और साथ ही उत्पादन घटाया। इसका उपचार कठिन है, क्योंकि मुद्रास्फीति रोकने के लिए दरें बढ़ाने से मंदी और गहरी होती है।','econ-stagflation','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','mcq','medium','Personal disposable income is:','वैयक्तिक प्रयोज्य आय (personal disposable income) क्या है?','{}'::jsonb,'[{"id": "a", "body": "personal income minus direct taxes and compulsory fees", "body_hi": "वैयक्तिक आय में से प्रत्यक्ष कर और अनिवार्य शुल्क घटाकर", "isCorrect": true}, {"id": "b", "body": "national income plus all transfer payments made by the government", "body_hi": "राष्ट्रीय आय और सरकार द्वारा किए गए सभी हस्तांतरण भुगतानों का योग", "isCorrect": false}, {"id": "c", "body": "GDP minus depreciation", "body_hi": "GDP में से मूल्यह्रास घटाकर", "isCorrect": false}, {"id": "d", "body": "the total income of the corporate sector after taxes", "body_hi": "करों के बाद निगमित क्षेत्र की कुल आय", "isCorrect": false}]'::jsonb,2,0.66,'Personal disposable income is what households can actually spend or save: personal income -- which already includes transfers such as pensions -- minus personal income tax and compulsory fees and fines. GDP minus depreciation is net domestic product.','वैयक्तिक प्रयोज्य आय वह है जिसे परिवार वास्तव में ख़र्च या बचत कर सकते हैं: वैयक्तिक आय, जिसमें पेंशन जैसे हस्तांतरण पहले से शामिल हैं, में से व्यक्तिगत आयकर और अनिवार्य शुल्क तथा जुर्माने घटाकर। GDP में से मूल्यह्रास घटाने पर शुद्ध घरेलू उत्पाद मिलता है।','econ-personal-disposable-income','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- National Income Accounting.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','mcq','easy','Which one of the following is a final good?','निम्नलिखित में से कौन-सी अंतिम वस्तु (final good) है?','{}'::jsonb,'[{"id": "a", "body": "Flour bought by a bakery", "body_hi": "एक बेकरी द्वारा ख़रीदा गया आटा", "isCorrect": false}, {"id": "b", "body": "Steel bought by a car maker", "body_hi": "एक कार निर्माता द्वारा ख़रीदा गया इस्पात", "isCorrect": false}, {"id": "c", "body": "Cotton bought by a textile mill", "body_hi": "एक कपड़ा मिल द्वारा ख़रीदी गई कपास", "isCorrect": false}, {"id": "d", "body": "Bread bought by a family", "body_hi": "एक परिवार द्वारा ख़रीदी गई ब्रेड", "isCorrect": true}]'::jsonb,2,0.66,'A final good is bought for final use, not to be processed further or resold; the bread a family eats is final, while flour, steel and cotton bought by producers are intermediate goods. Only final goods are counted in GDP, to avoid counting the same value twice.','अंतिम वस्तु अंतिम उपयोग के लिए ख़रीदी जाती है, आगे संसाधित करने या फिर से बेचने के लिए नहीं; परिवार द्वारा खाई जाने वाली ब्रेड अंतिम वस्तु है, जबकि उत्पादकों द्वारा ख़रीदे गए आटा, इस्पात और कपास मध्यवर्ती वस्तुएँ हैं। एक ही मूल्य को दो बार गिनने से बचने के लिए GDP में केवल अंतिम वस्तुएँ गिनी जाती हैं।','econ-final-good-easy','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- National Income Accounting.','draft'),
('upsc','Economy','Macro Concepts, National Income & Inflation','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "A rise in the marginal propensity to consume increases the size of the investment multiplier.", "assertion_hi": "सीमांत उपभोग प्रवृत्ति (MPC) में वृद्धि निवेश गुणक के आकार को बढ़ाती है।", "reason": "The investment multiplier equals 1 divided by (1 minus the marginal propensity to consume).", "reason_hi": "निवेश गुणक 1 को (1 घटा सीमांत उपभोग प्रवृत्ति) से भाग देने के बराबर होता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. If people spend 80 paise of every extra rupee, the multiplier is 1/(1-0.8) = 5: an extra 100 crore of investment can raise income by about 500 crore as each round of spending becomes someone else''s income. The more of each rupee that is spent rather than saved, the larger the multiplier.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। यदि लोग हर अतिरिक्त रुपये में से 80 पैसे ख़र्च करते हैं, तो गुणक 1/(1-0.8) = 5 है: 100 करोड़ का अतिरिक्त निवेश आय को लगभग 500 करोड़ तक बढ़ा सकता है, क्योंकि ख़र्च का हर दौर किसी और की आय बन जाता है। हर रुपये का जितना अधिक भाग बचाने के बजाय ख़र्च होता है, गुणक उतना बड़ा होता है।','econ-investment-multiplier','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Determination of Income and Employment.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about the Monetary Policy Committee (MPC):','मौद्रिक नीति समिति (MPC) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The MPC has six members, three of whom are from the RBI.", "In case of a tie, the Governor of the RBI has a casting vote.", "The external members of the MPC are appointed by the RBI''s Central Board."], "statements_hi": ["MPC के छह सदस्य हैं, जिनमें से तीन RBI से होते हैं।", "मत बराबर होने पर RBI के गवर्नर के पास निर्णायक मत होता है।", "MPC के बाहरी सदस्य RBI के केंद्रीय बोर्ड द्वारा नियुक्त किए जाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. Under section 45ZB of the RBI Act, the MPC consists of the Governor (chairperson), the Deputy Governor in charge of monetary policy and one officer nominated by the Central Board, plus three outside members; decisions are by majority, with the Governor''s second or casting vote in a tie. Statement 3 is wrong: the three external members are appointed by the Central Government, on a search-committee recommendation, for four years and are not eligible for reappointment.','कथन 1 और 2 सही हैं। RBI अधिनियम की धारा 45ZB के तहत MPC में गवर्नर (अध्यक्ष), मौद्रिक नीति के प्रभारी डिप्टी गवर्नर और केंद्रीय बोर्ड द्वारा नामित एक अधिकारी, और तीन बाहरी सदस्य होते हैं; निर्णय बहुमत से होते हैं, और बराबरी पर गवर्नर का दूसरा या निर्णायक मत होता है। कथन 3 गलत है: तीनों बाहरी सदस्यों को केंद्र सरकार एक खोज समिति की सिफ़ारिश पर चार वर्ष के लिए नियुक्त करती है, और वे पुनर्नियुक्ति के पात्र नहीं होते।','econ-mpc-composition','original_pattern_matched','Reserve Bank of India Act, 1934, sections 45ZA-45ZB.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about India''s flexible inflation-targeting framework:','भारत के लचीले मुद्रास्फीति-लक्ष्यीकरण ढाँचे के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The inflation target is set by the Central Government in consultation with the RBI.", "The target notified for 2021-26 was 4 per cent CPI inflation, with a tolerance band of 2 to 6 per cent.", "The framework has statutory backing in the RBI Act, 1934.", "The RBI must explain its failure to the government if inflation stays outside the band for two consecutive months."], "statements_hi": ["मुद्रास्फीति लक्ष्य केंद्र सरकार RBI के परामर्श से तय करती है।", "2021-26 के लिए अधिसूचित लक्ष्य 4 प्रतिशत CPI मुद्रास्फीति था, जिसकी सहनशीलता सीमा 2 से 6 प्रतिशत थी।", "इस ढाँचे को RBI अधिनियम, 1934 में वैधानिक आधार प्राप्त है।", "यदि मुद्रास्फीति लगातार दो महीने तक सीमा से बाहर रहे, तो RBI को सरकार को अपनी विफलता का कारण बताना होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "Only three", "body_hi": "केवल तीन", "isCorrect": true}, {"id": "d", "body": "All four", "body_hi": "सभी चार", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1, 2 and 3 are correct. The Finance Act, 2016 inserted section 45ZA into the RBI Act, under which the government notifies the target once every five years; the first target, for 2016-21, was retained for 2021-26. Statement 4 is wrong: failure means average inflation above the upper or below the lower tolerance level for three consecutive quarters; the RBI must then report the reasons, the remedial action proposed and the time it expects to take.','कथन 1, 2 और 3 सही हैं। वित्त अधिनियम, 2016 ने RBI अधिनियम में धारा 45ZA जोड़ी, जिसके तहत सरकार हर पाँच वर्ष में एक बार लक्ष्य अधिसूचित करती है; 2016-21 का पहला लक्ष्य 2021-26 के लिए भी बनाए रखा गया। कथन 4 गलत है: विफलता का अर्थ है लगातार तीन तिमाहियों तक औसत मुद्रास्फीति का ऊपरी सहनशीलता स्तर से ऊपर या निचले स्तर से नीचे रहना; तब RBI को कारण, प्रस्तावित सुधारात्मक कदम और उसमें लगने वाला अनुमानित समय बताना होता है।','econ-inflation-targeting-framework','original_pattern_matched','Reserve Bank of India Act, 1934, section 45ZA; Ministry of Finance notification of March 2021.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about the RBI''s liquidity instruments:','RBI के तरलता उपकरणों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Standing Deposit Facility lets the RBI absorb surplus liquidity without giving government securities as collateral.", "The Marginal Standing Facility rate is lower than the policy repo rate.", "Under the Marginal Standing Facility, banks can dip into their SLR holdings up to a limit to borrow overnight."], "statements_hi": ["स्थायी जमा सुविधा (SDF) RBI को बदले में सरकारी प्रतिभूतियाँ दिए बिना अतिरिक्त तरलता सोखने देती है।", "सीमांत स्थायी सुविधा (MSF) दर नीतिगत रेपो दर से कम होती है।", "MSF के तहत बैंक रातभर उधार लेने के लिए एक सीमा तक अपनी SLR प्रतिभूतियों का उपयोग कर सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. The SDF, introduced in April 2022, is a collateral-free deposit window that now forms the floor of the liquidity adjustment facility corridor; the MSF is the emergency borrowing window, where banks may pledge even securities they hold to meet the SLR, up to a set share of their deposits. Statement 2 is wrong: the MSF rate sits above the repo rate and forms the ceiling of the corridor -- borrowing in an emergency is meant to be costlier. The Bank Rate is aligned with the MSF rate.','कथन 1 और 3 सही हैं। अप्रैल 2022 में शुरू की गई SDF बिना संपार्श्विक (collateral) वाली जमा खिड़की है, जो अब तरलता समायोजन सुविधा गलियारे का निचला स्तर (floor) है; MSF आपातकालीन उधार खिड़की है, जिसमें बैंक अपनी जमा राशि के एक निर्धारित हिस्से तक SLR के लिए रखी प्रतिभूतियाँ भी गिरवी रख सकते हैं। कथन 2 गलत है: MSF दर रेपो दर से ऊपर होती है और गलियारे की ऊपरी सीमा (ceiling) बनाती है, क्योंकि आपातकाल में उधार लेना जान-बूझकर महँगा रखा जाता है। बैंक दर MSF दर के बराबर रखी जाती है।','econ-sdf-msf-corridor','original_pattern_matched','Reserve Bank of India -- Liquidity Adjustment Facility; Monetary Policy Statements.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about reserve requirements:','आरक्षित आवश्यकताओं के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Banks earn no interest from the RBI on the balances they keep to meet the Cash Reserve Ratio.", "The Statutory Liquidity Ratio can be met with cash, gold or approved government securities.", "A cut in the Cash Reserve Ratio increases the lendable resources of banks."], "statements_hi": ["नकद आरक्षित अनुपात (CRR) पूरा करने के लिए रखी गई राशि पर बैंकों को RBI से कोई ब्याज नहीं मिलता।", "सांविधिक तरलता अनुपात (SLR) नकदी, सोने या अनुमोदित सरकारी प्रतिभूतियों से पूरा किया जा सकता है।", "CRR में कटौती से बैंकों के उधार देने योग्य संसाधन बढ़ जाते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. CRR balances, held with the RBI as a share of net demand and time liabilities, earn nothing, so a CRR cut both releases funds for lending and lowers banks'' costs. SLR assets are held by banks themselves, and because government securities dominate them, the SLR also creates a steady demand for government debt.','तीनों कथन सही हैं। शुद्ध माँग और सावधि देयताओं के एक हिस्से के रूप में RBI के पास रखी जाने वाली CRR राशि पर कुछ नहीं मिलता, इसलिए CRR में कटौती उधार के लिए धन भी मुक्त करती है और बैंकों की लागत भी घटाती है। SLR परिसंपत्तियाँ बैंक स्वयं रखते हैं, और चूँकि इनमें सरकारी प्रतिभूतियों का वर्चस्व है, SLR सरकारी ऋण के लिए एक स्थिर माँग भी पैदा करता है।','econ-crr-slr','original_pattern_matched','Reserve Bank of India Act, 1934, section 42; Banking Regulation Act, 1949, section 24.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about the measures of money supply:','मुद्रा आपूर्ति के मापों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Broad money (M3) includes time deposits with banks.", "Currency held by banks in their own vaults is part of M1.", "M1 is a broader measure of money than M3."], "statements_hi": ["व्यापक मुद्रा (M3) में बैंकों की सावधि जमाएँ शामिल हैं।", "बैंकों के अपने तिजोरियों में रखी मुद्रा M1 का भाग है।", "M1, M3 से अधिक व्यापक मुद्रा माप है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: M3 = M1 + time deposits with banks, and it is the measure most watched for monetary growth. Statement 2 is wrong: M1 counts currency with the public, demand deposits with banks and other deposits with the RBI; cash in banks'' own vaults is not money in the hands of the public and is excluded. Statement 3 is wrong: M1 is the narrowest measure of money held by the public; M3 adds time deposits to it.','केवल कथन 1 सही है: M3 = M1 + बैंकों की सावधि जमाएँ, और मौद्रिक वृद्धि के लिए सबसे अधिक इसी माप पर नज़र रखी जाती है। कथन 2 गलत है: M1 में जनता के पास मुद्रा, बैंकों में माँग जमाएँ और RBI के पास अन्य जमाएँ गिनी जाती हैं; बैंकों की अपनी तिजोरियों की नकदी जनता के हाथ की मुद्रा नहीं है और बाहर रहती है। कथन 3 गलत है: M1 जनता के पास मुद्रा का सबसे संकीर्ण माप है; M3 इसमें सावधि जमाएँ जोड़ता है।','econ-money-supply-measures','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Money and Banking; Reserve Bank of India -- Handbook of Statistics on the Indian Economy.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about the Reserve Bank of India:','भारतीय रिज़र्व बैंक के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The RBI manages the public debt of the Central Government.", "One-rupee notes are issued by the RBI.", "The RBI pays income tax on its surplus before transferring it to the government."], "statements_hi": ["RBI केंद्र सरकार के लोक ऋण का प्रबंधन करता है।", "एक रुपये के नोट RBI द्वारा जारी किए जाते हैं।", "RBI सरकार को अधिशेष हस्तांतरित करने से पहले उस पर आयकर देता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: the RBI issues and manages the Centre''s market borrowings, and those of the States by agreement; a separate public debt management agency has been discussed for years but not set up. Statement 2 is wrong: one-rupee notes, like coins, are issued by the Government of India and carry the Finance Secretary''s signature; all other notes are issued by the RBI. Statement 3 is wrong: under section 48 of the RBI Act the Bank pays no income tax; after setting aside provisions under its Economic Capital Framework, it transfers the balance of its profits to the Centre.','केवल कथन 1 सही है: RBI केंद्र के बाज़ार उधार, और समझौते के आधार पर राज्यों के उधार भी, जारी करता है और उनका प्रबंधन करता है; एक अलग लोक ऋण प्रबंधन एजेंसी पर वर्षों से चर्चा हुई है, पर वह बनी नहीं। कथन 2 गलत है: एक रुपये के नोट, सिक्कों की तरह, भारत सरकार जारी करती है और उन पर वित्त सचिव के हस्ताक्षर होते हैं; अन्य सभी नोट RBI जारी करता है। कथन 3 गलत है: RBI अधिनियम की धारा 48 के तहत बैंक कोई आयकर नहीं देता; अपने आर्थिक पूँजी ढाँचे (Economic Capital Framework) के तहत प्रावधान अलग रखने के बाद वह शेष लाभ केंद्र को हस्तांतरित कर देता है।','econ-rbi-functions-debt-notes-tax','original_pattern_matched','Reserve Bank of India Act, 1934, sections 21, 47 and 48; Currency Ordinance, 1940.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about differentiated banks:','विभेदित (differentiated) बैंकों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Payments banks cannot lend.", "Payments banks can issue credit cards.", "Small finance banks must lend 75 per cent of their adjusted net bank credit to the priority sectors."], "statements_hi": ["भुगतान बैंक ऋण नहीं दे सकते।", "भुगतान बैंक क्रेडिट कार्ड जारी कर सकते हैं।", "लघु वित्त बैंकों को अपने समायोजित शुद्ध बैंक ऋण का 75 प्रतिशत प्राथमिकता वाले क्षेत्रों को देना होता है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Licensed from 2015 to widen financial inclusion, payments banks take deposits of up to 2 lakh rupees per customer and offer remittances and debit cards, investing their funds in government securities and bank deposits; small finance banks serve small farmers, micro and small units and the unorganised sector. Statement 2 is wrong: payments banks cannot issue credit cards, because a credit card is a form of lending.','कथन 1 और 3 सही हैं। वित्तीय समावेशन बढ़ाने के लिए 2015 से लाइसेंस पाए भुगतान बैंक प्रति ग्राहक 2 लाख रुपये तक की जमाएँ लेते हैं और धन-प्रेषण तथा डेबिट कार्ड की सुविधा देते हैं, और अपना धन सरकारी प्रतिभूतियों और बैंक जमाओं में लगाते हैं; लघु वित्त बैंक छोटे किसानों, सूक्ष्म और लघु इकाइयों तथा असंगठित क्षेत्र को सेवा देते हैं। कथन 2 गलत है: भुगतान बैंक क्रेडिट कार्ड जारी नहीं कर सकते, क्योंकि क्रेडिट कार्ड ऋण देने का ही एक रूप है।','econ-payments-small-finance-banks','original_pattern_matched','Reserve Bank of India -- Guidelines for Licensing of Payments Banks and of Small Finance Banks.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about non-banking financial companies (NBFCs):','गैर-बैंकिंग वित्तीय कंपनियों (NBFC) के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["NBFCs can accept demand deposits.", "Deposits with NBFCs are covered by the deposit insurance of the DICGC.", "NBFCs are part of the payment and settlement system and can issue cheques drawn on themselves."], "statements_hi": ["NBFC माँग जमाएँ स्वीकार कर सकती हैं।", "NBFC में जमा राशि DICGC के जमा बीमा के दायरे में आती है।", "NBFC भुगतान और निपटान प्रणाली का भाग हैं और स्वयं पर आहरित चेक जारी कर सकती हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": true}]'::jsonb,2,0.66,'None of the statements is correct. These three limits are exactly what separate an NBFC from a bank: NBFCs cannot accept demand deposits (only some deposit-taking NBFCs may accept term deposits), they are not part of the payment and settlement system and cannot issue cheques, and their deposits carry no DICGC insurance. They are regulated by the RBI under a scale-based framework, with the largest in the ''upper layer'' supervised much like banks.','कोई भी कथन सही नहीं है। ठीक यही तीन सीमाएँ NBFC को बैंक से अलग करती हैं: NBFC माँग जमाएँ स्वीकार नहीं कर सकतीं (केवल कुछ जमा लेने वाली NBFC सावधि जमाएँ ले सकती हैं), वे भुगतान और निपटान प्रणाली का भाग नहीं हैं और चेक जारी नहीं कर सकतीं, और उनकी जमाओं पर DICGC का बीमा नहीं होता। RBI इन्हें पैमाने-आधारित ढाँचे के तहत विनियमित करता है, जिसमें सबसे बड़ी ''ऊपरी परत'' वाली NBFC की निगरानी लगभग बैंकों की तरह होती है।','econ-nbfc-vs-banks','original_pattern_matched','Reserve Bank of India -- Scale Based Regulation for NBFCs (2021); FAQs on NBFCs.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The DICGC insures bank deposits up to 5 lakh rupees per depositor per bank.", "DICGC cover extends to deposits in cooperative banks.", "The Insolvency and Bankruptcy Code sets an outer limit of 330 days, including time spent in litigation, to complete a corporate insolvency resolution."], "statements_hi": ["DICGC प्रति जमाकर्ता प्रति बैंक 5 लाख रुपये तक की बैंक जमाओं का बीमा करता है।", "DICGC का बीमा सहकारी बैंकों की जमाओं पर भी लागू होता है।", "दिवाला और शोधन अक्षमता संहिता (IBC) कॉरपोरेट दिवाला समाधान पूरा करने के लिए मुक़दमेबाज़ी में लगे समय सहित 330 दिनों की अधिकतम सीमा तय करती है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": true}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'All three statements are correct. The deposit insurance cover was raised from 1 lakh to 5 lakh rupees in 2020, and a 2021 amendment made the DICGC pay insured depositors within about 90 days even while a failed bank is under moratorium; it covers commercial, regional rural, local area and most cooperative banks. The 2019 amendment to the IBC set the 330-day outer limit, which in practice is often exceeded.','तीनों कथन सही हैं। जमा बीमा सीमा 2020 में 1 लाख से बढ़ाकर 5 लाख रुपये की गई, और 2021 के एक संशोधन ने DICGC को असफल बैंक पर रोक (moratorium) के दौरान भी बीमित जमाकर्ताओं को लगभग 90 दिनों में भुगतान करने को कहा; यह वाणिज्यिक, क्षेत्रीय ग्रामीण, स्थानीय क्षेत्र और अधिकांश सहकारी बैंकों को शामिल करता है। IBC के 2019 के संशोधन ने 330 दिनों की अधिकतम सीमा तय की, जो व्यवहार में प्रायः पार हो जाती है।','econ-dicgc-ibc-timeline','original_pattern_matched','Deposit Insurance and Credit Guarantee Corporation Act, 1961 (amended 2021); Insolvency and Bankruptcy Code, 2016.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','medium','Consider the following statements about the banking system:','बैंकिंग प्रणाली के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Banking Regulation (Amendment) Act, 2020 strengthened the RBI''s regulatory control over cooperative banks.", "The Financial Services Institutions Bureau replaced the Banks Board Bureau.", "Regional Rural Banks are owned entirely by the State Governments."], "statements_hi": ["बैंकिंग विनियमन (संशोधन) अधिनियम, 2020 ने सहकारी बैंकों पर RBI के विनियामक नियंत्रण को मज़बूत किया।", "वित्तीय सेवा संस्थान ब्यूरो (FSIB) ने बैंक बोर्ड ब्यूरो का स्थान लिया।", "क्षेत्रीय ग्रामीण बैंकों का पूरा स्वामित्व राज्य सरकारों के पास है।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct. After the PMC Bank crisis of 2019, the 2020 amendment brought the management, capital and audit of urban and State-level cooperative banks under RBI regulation like other banks; the FSIB, set up in 2022, recommends heads of public sector banks and financial institutions. Statement 3 is wrong: Regional Rural Banks are owned jointly -- the Centre 50 per cent, the sponsor bank 35 per cent and the State Government 15 per cent; in 2025 they were consolidated on a ''one State, one RRB'' basis.','कथन 1 और 2 सही हैं। 2019 के PMC बैंक संकट के बाद, 2020 के संशोधन ने शहरी और राज्य-स्तरीय सहकारी बैंकों के प्रबंधन, पूँजी और लेखापरीक्षा को अन्य बैंकों की तरह RBI के विनियमन में ला दिया; 2022 में बना FSIB सार्वजनिक क्षेत्र के बैंकों और वित्तीय संस्थानों के प्रमुखों की सिफ़ारिश करता है। कथन 3 गलत है: क्षेत्रीय ग्रामीण बैंकों का स्वामित्व साझा है, यानी केंद्र 50 प्रतिशत, प्रायोजक बैंक 35 प्रतिशत और राज्य सरकार 15 प्रतिशत; 2025 में इन्हें ''एक राज्य, एक RRB'' के आधार पर समेकित किया गया।','econ-coop-banks-fsib-rrbs','original_pattern_matched','Banking Regulation (Amendment) Act, 2020; Ministry of Finance -- Department of Financial Services.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The Reserve Bank of India is India''s central bank.", "The Reserve Bank of India was set up in 1947."], "statements_hi": ["भारतीय रिज़र्व बैंक भारत का केंद्रीय बैंक है।", "भारतीय रिज़र्व बैंक की स्थापना 1947 में हुई।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": true}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct. Statement 2 is wrong: the RBI began operations on 1 April 1935 under the RBI Act, 1934, as a shareholders'' bank, and was nationalised on 1 January 1949.','केवल कथन 1 सही है। कथन 2 गलत है: RBI ने RBI अधिनियम, 1934 के तहत 1 अप्रैल 1935 को एक शेयरधारकों के बैंक के रूप में काम शुरू किया, और 1 जनवरी 1949 को इसका राष्ट्रीयकरण किया गया।','econ-rbi-established-easy','original_pattern_matched','Reserve Bank of India -- History.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The RBI accepts savings deposits from individuals.", "Commercial banks accept deposits from the public and lend to borrowers."], "statements_hi": ["RBI व्यक्तियों से बचत जमाएँ स्वीकार करता है।", "वाणिज्यिक बैंक जनता से जमाएँ स्वीकार करते हैं और उधारकर्ताओं को ऋण देते हैं।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": true}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": false}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 2 is correct. Statement 1 is wrong: the RBI is the bankers'' bank and the government''s banker; it does not open savings accounts for the public, although individuals can now open a ''Retail Direct'' account with it to buy government securities.','केवल कथन 2 सही है। कथन 1 गलत है: RBI बैंकों का बैंक और सरकार का बैंकर है; यह जनता के लिए बचत खाते नहीं खोलता, यद्यपि अब व्यक्ति सरकारी प्रतिभूतियाँ ख़रीदने के लिए इसके पास ''रिटेल डायरेक्ट'' खाता खोल सकते हैं।','econ-rbi-vs-commercial-banks-easy','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Money and Banking.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["The repo rate is the rate at which the RBI lends to banks against government securities.", "A higher repo rate usually makes bank loans costlier."], "statements_hi": ["रेपो दर वह दर है जिस पर RBI सरकारी प्रतिभूतियों के बदले बैंकों को उधार देता है।", "ऊँची रेपो दर प्रायः बैंक ऋणों को महँगा बनाती है।"], "closing": "Which of the statements given above is/are correct?", "closing_hi": "उपर्युक्त कथनों में से कौन-सा/से सही है/हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "1 only", "body_hi": "केवल 1", "isCorrect": false}, {"id": "b", "body": "2 only", "body_hi": "केवल 2", "isCorrect": false}, {"id": "c", "body": "Both 1 and 2", "body_hi": "1 और 2 दोनों", "isCorrect": true}, {"id": "d", "body": "Neither 1 nor 2", "body_hi": "न तो 1, न ही 2", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct. When the repo rate rises, banks'' cost of funds goes up and, because many loans are now linked to external benchmarks such as the repo rate, lending rates follow -- one of the main ways monetary policy cools demand.','दोनों कथन सही हैं। रेपो दर बढ़ने पर बैंकों की धन की लागत बढ़ जाती है, और चूँकि अब कई ऋण रेपो दर जैसे बाहरी मानकों से जुड़े हैं, इसलिए ऋण दरें भी बढ़ती हैं; यह माँग को ठंडा करने का मौद्रिक नीति का एक मुख्य तरीक़ा है।','econ-repo-rate-easy','original_pattern_matched','Reserve Bank of India -- Monetary Policy.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','hard','Consider the following statements about the Basel III norms:','बेसल III मानदंडों के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Basel III introduced a capital conservation buffer of 2.5 per cent of risk-weighted assets.", "India''s minimum capital to risk-weighted assets ratio for banks is lower than the Basel III minimum.", "Basel III introduced a leverage ratio and a liquidity coverage ratio."], "statements_hi": ["बेसल III ने जोखिम-भारित परिसंपत्तियों के 2.5 प्रतिशत का पूँजी संरक्षण बफ़र शुरू किया।", "बैंकों के लिए भारत का न्यूनतम पूँजी से जोखिम-भारित परिसंपत्ति अनुपात बेसल III के न्यूनतम से कम है।", "बेसल III ने उत्तोलन (leverage) अनुपात और तरलता कवरेज अनुपात शुरू किए।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 3 are correct. Framed after the 2008 crisis, Basel III raised the quality and quantity of capital, added the conservation buffer that banks can draw down in bad times, capped leverage regardless of risk weights, and required banks to hold enough high-quality liquid assets to survive a 30-day stress. Statement 2 is wrong: India is stricter -- the RBI requires a minimum CRAR of 9 per cent (11.5 per cent with the buffer) against Basel''s 8 per cent (10.5).','कथन 1 और 3 सही हैं। 2008 के संकट के बाद बने बेसल III ने पूँजी की गुणवत्ता और मात्रा बढ़ाई, संरक्षण बफ़र जोड़ा जिसे बैंक बुरे समय में उपयोग कर सकते हैं, जोखिम भार से स्वतंत्र उत्तोलन पर सीमा लगाई, और बैंकों से 30 दिन के दबाव को झेलने लायक उच्च गुणवत्ता की तरल परिसंपत्तियाँ रखने को कहा। कथन 2 गलत है: भारत अधिक कड़ा है; RBI बेसल के 8 प्रतिशत (बफ़र सहित 10.5) के मुक़ाबले न्यूनतम 9 प्रतिशत CRAR (बफ़र सहित 11.5 प्रतिशत) की अपेक्षा करता है।','econ-basel-iii','original_pattern_matched','Reserve Bank of India -- Master Circular on Basel III Capital Regulations; Basel Committee on Banking Supervision.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','hard','Consider the following statements about priority sector lending:','प्राथमिकता क्षेत्र ऋण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Domestic scheduled commercial banks must lend 40 per cent of their adjusted net bank credit to the priority sectors.", "Within this, 18 per cent of adjusted net bank credit must go to agriculture.", "Trading in Priority Sector Lending Certificates involves transferring the underlying loans from one bank to another."], "statements_hi": ["घरेलू अनुसूचित वाणिज्यिक बैंकों को अपने समायोजित शुद्ध बैंक ऋण का 40 प्रतिशत प्राथमिकता वाले क्षेत्रों को देना होता है।", "इसमें से समायोजित शुद्ध बैंक ऋण का 18 प्रतिशत कृषि को जाना चाहिए।", "प्राथमिकता क्षेत्र ऋण प्रमाणपत्रों (PSLC) के व्यापार में अंतर्निहित ऋण एक बैंक से दूसरे बैंक को हस्तांतरित होते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": false}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": true}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Statements 1 and 2 are correct; the 18 per cent for agriculture includes a sub-target for small and marginal farmers, and there are separate sub-targets for micro enterprises and weaker sections. Statement 3 is wrong: a PSLC lets a bank that has over-achieved sell its surplus achievement to one that has fallen short -- only the obligation changes hands; the loans, and their credit risk, stay with the lending bank.','कथन 1 और 2 सही हैं; कृषि के 18 प्रतिशत में छोटे और सीमांत किसानों के लिए एक उप-लक्ष्य भी है, और सूक्ष्म उद्यमों तथा कमज़ोर वर्गों के लिए अलग उप-लक्ष्य हैं। कथन 3 गलत है: PSLC लक्ष्य से अधिक उपलब्धि वाले बैंक को अपनी अतिरिक्त उपलब्धि उस बैंक को बेचने देता है जो पीछे रह गया है; केवल दायित्व का हस्तांतरण होता है, ऋण और उनका ऋण-जोखिम उधार देने वाले बैंक के पास ही रहते हैं।','econ-priority-sector-pslc','original_pattern_matched','Reserve Bank of India -- Master Directions on Priority Sector Lending; Priority Sector Lending Certificates.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','statement_based','hard','Consider the following statements about the pricing of bank loans:','बैंक ऋणों के मूल्य-निर्धारण के बारे में निम्नलिखित कथनों पर विचार कीजिए:','{"statements": ["Since October 2019, banks must link new floating-rate retail and MSE loans to an external benchmark such as the policy repo rate.", "The MCLR system directly replaced the benchmark prime lending rate system.", "Banks may reset the spread over the external benchmark whenever they wish."], "statements_hi": ["अक्टूबर 2019 से बैंकों को नए अस्थिर-दर (floating-rate) खुदरा और MSE ऋणों को नीतिगत रेपो दर जैसे किसी बाहरी मानक से जोड़ना अनिवार्य है।", "MCLR प्रणाली ने सीधे बेंचमार्क प्राइम लेंडिंग रेट प्रणाली का स्थान लिया।", "बैंक बाहरी मानक के ऊपर का अंतर (spread) जब चाहें बदल सकते हैं।"], "closing": "How many of the above statements are correct?", "closing_hi": "उपर्युक्त में से कितने कथन सही हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one", "body_hi": "केवल एक", "isCorrect": true}, {"id": "b", "body": "Only two", "body_hi": "केवल दो", "isCorrect": false}, {"id": "c", "body": "All three", "body_hi": "सभी तीन", "isCorrect": false}, {"id": "d", "body": "None", "body_hi": "कोई नहीं", "isCorrect": false}]'::jsonb,2,0.66,'Only statement 1 is correct: external benchmark lending was introduced because changes in the policy rate were passing slowly into lending rates under internally set benchmarks. Statement 2 is wrong: the sequence was BPLR, then the base rate (2010), then the marginal cost of funds-based lending rate (April 2016), and finally the external benchmark (2019). Statement 3 is wrong: the credit-risk part of the spread may be changed only if the borrower''s credit assessment changes substantially, as agreed in the loan contract, so that borrowers are not surprised.','केवल कथन 1 सही है: बाहरी मानक-आधारित ऋण इसलिए शुरू किया गया कि आंतरिक रूप से तय मानकों के तहत नीतिगत दर में बदलाव ऋण दरों तक धीरे पहुँच रहे थे। कथन 2 गलत है: क्रम था BPLR, फिर आधार दर (2010), फिर निधियों की सीमांत लागत पर आधारित उधार दर (MCLR, अप्रैल 2016), और अंत में बाहरी मानक (2019)। कथन 3 गलत है: अंतर का ऋण-जोखिम वाला भाग केवल तभी बदला जा सकता है जब उधारकर्ता के ऋण मूल्यांकन में, ऋण अनुबंध के अनुसार, पर्याप्त परिवर्तन हो, ताकि उधारकर्ता अचंभित न हों।','econ-loan-pricing-ebllr-mclr','original_pattern_matched','Reserve Bank of India -- Master Direction on Interest Rate on Advances (External Benchmark, 2019).','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','mcq','medium','Which one of the following is NOT a quantitative instrument of monetary policy?','निम्नलिखित में से कौन-सा मौद्रिक नीति का परिमाणात्मक (quantitative) उपकरण नहीं है?','{}'::jsonb,'[{"id": "a", "body": "Cash Reserve Ratio", "body_hi": "नकद आरक्षित अनुपात", "isCorrect": false}, {"id": "b", "body": "Moral suasion", "body_hi": "नैतिक अनुनय (moral suasion)", "isCorrect": true}, {"id": "c", "body": "Open market operations", "body_hi": "खुले बाज़ार की क्रियाएँ", "isCorrect": false}, {"id": "d", "body": "The policy repo rate", "body_hi": "नीतिगत रेपो दर", "isCorrect": false}]'::jsonb,2,0.66,'Quantitative (general) instruments change the overall cost and quantity of credit -- the repo rate, CRR, SLR and open market operations. Moral suasion -- persuading banks through advice, letters and meetings -- is a qualitative, selective instrument, like margin requirements on particular loans.','परिमाणात्मक (सामान्य) उपकरण ऋण की समग्र लागत और मात्रा बदलते हैं, जैसे रेपो दर, CRR, SLR और खुले बाज़ार की क्रियाएँ। नैतिक अनुनय, यानी सलाह, पत्रों और बैठकों के ज़रिए बैंकों को समझाना, विशेष ऋणों पर मार्जिन आवश्यकताओं की तरह एक गुणात्मक, चयनात्मक उपकरण है।','econ-qualitative-moral-suasion','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Money and Banking; Reserve Bank of India -- Monetary Policy.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','mcq','medium','Which one of the following RBI actions would reduce liquidity in the banking system?','RBI की निम्नलिखित में से कौन-सी कार्रवाई बैंकिंग प्रणाली में तरलता घटाएगी?','{}'::jsonb,'[{"id": "a", "body": "Cutting the policy repo rate", "body_hi": "नीतिगत रेपो दर घटाना", "isCorrect": false}, {"id": "b", "body": "Lowering the Statutory Liquidity Ratio", "body_hi": "सांविधिक तरलता अनुपात घटाना", "isCorrect": false}, {"id": "c", "body": "Raising the Cash Reserve Ratio", "body_hi": "नकद आरक्षित अनुपात बढ़ाना", "isCorrect": true}, {"id": "d", "body": "Allowing banks to borrow more under the Marginal Standing Facility", "body_hi": "बैंकों को सीमांत स्थायी सुविधा के तहत अधिक उधार लेने देना", "isCorrect": false}]'::jsonb,2,0.66,'A higher CRR makes banks lock up a larger share of their deposits with the RBI, draining funds from the system at a stroke. A repo-rate cut, a lower SLR and wider access to the MSF all make funds cheaper or more plentiful.','ऊँचा CRR बैंकों को अपनी जमाओं का बड़ा भाग RBI के पास रोककर रखने को विवश करता है, जिससे प्रणाली से एक झटके में धन निकल जाता है। रेपो दर में कटौती, कम SLR और MSF तक अधिक पहुँच, ये सब धन को सस्ता या अधिक उपलब्ध बनाते हैं।','econ-reduce-liquidity-crr','original_pattern_matched','Reserve Bank of India -- Monetary Policy.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','mcq','medium','The Deposit Insurance and Credit Guarantee Corporation (DICGC) is a wholly owned subsidiary of:','निक्षेप बीमा और प्रत्यय गारंटी निगम (DICGC) किसकी पूर्ण स्वामित्व वाली सहायक संस्था है?','{}'::jsonb,'[{"id": "a", "body": "the Reserve Bank of India", "body_hi": "भारतीय रिज़र्व बैंक", "isCorrect": true}, {"id": "b", "body": "the Ministry of Finance", "body_hi": "वित्त मंत्रालय", "isCorrect": false}, {"id": "c", "body": "the State Bank of India", "body_hi": "भारतीय स्टेट बैंक", "isCorrect": false}, {"id": "d", "body": "the Life Insurance Corporation of India", "body_hi": "भारतीय जीवन बीमा निगम", "isCorrect": false}]'::jsonb,2,0.66,'The DICGC, formed in 1978 by merging the Deposit Insurance Corporation (1962) with the Credit Guarantee Corporation, is wholly owned by the RBI. Banks pay it a premium on their assessable deposits, and it pays depositors when a bank fails or is placed under restrictions.','1962 के निक्षेप बीमा निगम और प्रत्यय गारंटी निगम को मिलाकर 1978 में बना DICGC पूरी तरह RBI के स्वामित्व में है। बैंक अपनी मूल्यांकन योग्य जमाओं पर इसे प्रीमियम देते हैं, और किसी बैंक के विफल होने या उस पर प्रतिबंध लगने पर यह जमाकर्ताओं को भुगतान करता है।','econ-dicgc-rbi-subsidiary','original_pattern_matched','Deposit Insurance and Credit Guarantee Corporation.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','mcq','easy','In India, the ''lender of last resort'' to the banking system is:','भारत में बैंकिंग प्रणाली का ''अंतिम ऋणदाता'' (lender of last resort) कौन है?','{}'::jsonb,'[{"id": "a", "body": "the State Bank of India", "body_hi": "भारतीय स्टेट बैंक", "isCorrect": false}, {"id": "b", "body": "NABARD", "body_hi": "नाबार्ड", "isCorrect": false}, {"id": "c", "body": "the Ministry of Finance of the Government of India", "body_hi": "भारत सरकार का वित्त मंत्रालय", "isCorrect": false}, {"id": "d", "body": "the Reserve Bank of India", "body_hi": "भारतीय रिज़र्व बैंक", "isCorrect": true}]'::jsonb,2,0.66,'As the central bank, the RBI stands ready to lend to solvent banks that face a sudden shortage of funds, so that a run on one bank does not spread through the system. This role, together with issuing currency, is what makes it the bankers'' bank.','केंद्रीय बैंक के रूप में RBI उन सक्षम बैंकों को उधार देने के लिए तैयार रहता है जिन्हें अचानक धन की कमी हो, ताकि किसी एक बैंक पर हुई भगदड़ पूरी प्रणाली में न फैले। मुद्रा जारी करने के साथ यही भूमिका उसे बैंकों का बैंक बनाती है।','econ-lender-of-last-resort-easy','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Money and Banking.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','mcq','hard','Other things remaining the same, which one of the following would increase the money multiplier?','अन्य बातें समान रहने पर, निम्नलिखित में से कौन-सा मुद्रा गुणक को बढ़ाएगा?','{}'::jsonb,'[{"id": "a", "body": "An increase in the Cash Reserve Ratio", "body_hi": "नकद आरक्षित अनुपात में वृद्धि", "isCorrect": false}, {"id": "b", "body": "A fall in the share of money that people hold as cash", "body_hi": "लोगों द्वारा नकदी के रूप में रखी जाने वाली मुद्रा के हिस्से में गिरावट", "isCorrect": true}, {"id": "c", "body": "Banks choosing to hold more excess reserves", "body_hi": "बैंकों द्वारा अधिक अतिरिक्त आरक्षित रखना", "isCorrect": false}, {"id": "d", "body": "A rise in cash withdrawals from banks during a festival season", "body_hi": "त्योहार के मौसम में बैंकों से नकद निकासी में वृद्धि", "isCorrect": false}]'::jsonb,2,0.66,'Money created by banks depends on how much of each rupee stays in the banking system to be lent again. When people keep less as cash and more as deposits, banks can lend more of it, and broad money rises for a given amount of reserve money. A higher CRR, larger excess reserves or heavier cash withdrawals all leak money out of the lending chain and lower the multiplier.','बैंकों द्वारा सृजित मुद्रा इस पर निर्भर करती है कि हर रुपये का कितना भाग फिर से उधार देने के लिए बैंकिंग प्रणाली में रहता है। जब लोग कम नकदी और अधिक जमा रखते हैं, तो बैंक उसका अधिक भाग उधार दे सकते हैं, और आरक्षित मुद्रा की दी गई मात्रा पर व्यापक मुद्रा बढ़ती है। ऊँचा CRR, अधिक अतिरिक्त आरक्षित या भारी नकद निकासी, ये सब मुद्रा को ऋण-श्रृंखला से बाहर रिसने देते हैं और गुणक घटाते हैं।','econ-money-multiplier-currency-ratio','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Money and Banking.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "When the RBI raises the policy repo rate, bank lending rates usually rise.", "assertion_hi": "जब RBI नीतिगत रेपो दर बढ़ाता है, तो बैंकों की ऋण दरें प्रायः बढ़ती हैं।", "reason": "A higher repo rate raises the cost at which banks obtain funds, and many loans are now directly linked to it.", "reason_hi": "ऊँची रेपो दर उस लागत को बढ़ाती है जिस पर बैंक धन प्राप्त करते हैं, और अब कई ऋण सीधे इससे जुड़े हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": true}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct and Statement-II explains Statement-I. This ''transmission'' is quickest for loans on external benchmarks, such as most home loans; loans on MCLR adjust more slowly, at their reset dates.','दोनों कथन सही हैं और कथन-II कथन-I की व्याख्या करता है। यह ''संचरण'' (transmission) बाहरी मानक वाले ऋणों में, जैसे अधिकांश गृह ऋणों में, सबसे तेज़ होता है; MCLR वाले ऋण अपनी पुनर्निर्धारण तिथियों पर धीरे-धीरे बदलते हैं।','econ-repo-transmission','original_pattern_matched','Reserve Bank of India -- Monetary Policy Report.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','assertion_reason','medium','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Open market operations are used by the RBI to manage liquidity in the banking system.", "assertion_hi": "RBI बैंकिंग प्रणाली में तरलता के प्रबंधन के लिए खुले बाज़ार की क्रियाओं का उपयोग करता है।", "reason": "Open market operations involve the RBI buying and selling the shares of listed companies.", "reason_hi": "खुले बाज़ार की क्रियाओं में RBI सूचीबद्ध कंपनियों के शेयर ख़रीदता और बेचता है।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": true}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Statement-I is correct but Statement-II is incorrect. In open market operations the RBI buys government securities to inject rupees and sells them to absorb rupees; it does not deal in corporate shares. It can also run variable-rate repo and reverse repo auctions and use forex swaps for the same purpose.','कथन-I सही है पर कथन-II गलत है। खुले बाज़ार की क्रियाओं में RBI रुपये डालने के लिए सरकारी प्रतिभूतियाँ ख़रीदता है और रुपये सोखने के लिए उन्हें बेचता है; वह कॉरपोरेट शेयरों में लेन-देन नहीं करता। इसी उद्देश्य से वह परिवर्ती दर रेपो और रिवर्स रेपो नीलामियाँ और विदेशी मुद्रा स्वैप भी कर सकता है।','econ-omo-government-securities','original_pattern_matched','Reserve Bank of India -- Liquidity Management Framework.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','assertion_reason','easy','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "Money kept in a bank savings account earns no interest.", "assertion_hi": "बैंक के बचत खाते में रखे पैसे पर कोई ब्याज नहीं मिलता।", "reason": "Banks earn by lending deposited money at a higher rate of interest than they pay depositors.", "reason_hi": "बैंक जमा किए गए पैसे को जमाकर्ताओं को दी जाने वाली दर से ऊँची ब्याज दर पर उधार देकर कमाते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": false}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": true}]'::jsonb,2,0.66,'Statement-I is incorrect but Statement-II is correct. Savings accounts do earn interest, though less than fixed deposits; banks can pay it because they lend the deposits at higher rates, and the gap between the two rates is their main source of income.','कथन-I गलत है पर कथन-II सही है। बचत खातों पर ब्याज मिलता है, यद्यपि सावधि जमाओं से कम; बैंक यह इसलिए दे पाते हैं कि वे जमाओं को ऊँची दरों पर उधार देते हैं, और दोनों दरों का अंतर उनकी आय का मुख्य स्रोत है।','econ-savings-interest-spread-easy','original_pattern_matched','NCERT Class XII, Introductory Macroeconomics -- Money and Banking.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','assertion_reason','hard','Consider the following statements:','निम्नलिखित कथनों पर विचार कीजिए:','{"assertion": "When the RBI buys foreign currency in large amounts to stop the rupee from rising, domestic money supply tends to increase.", "assertion_hi": "जब RBI रुपये को ऊपर चढ़ने से रोकने के लिए बड़ी मात्रा में विदेशी मुद्रा ख़रीदता है, तो घरेलू मुद्रा आपूर्ति बढ़ने लगती है।", "reason": "The RBI can offset this by selling government securities, which is called sterilisation.", "reason_hi": "RBI सरकारी प्रतिभूतियाँ बेचकर इसकी भरपाई कर सकता है, जिसे निष्फलीकरण (sterilisation) कहते हैं।", "ar_labels": "statement", "closing": "Which one of the following is correct in respect of the above statements?", "closing_hi": "उपर्युक्त कथनों के संदर्भ में, निम्नलिखित में से कौन-सा एक सही है?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Both Statement-I and Statement-II are correct and Statement-II is the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं और कथन-II, कथन-I की सही व्याख्या है", "isCorrect": false}, {"id": "b", "body": "Both Statement-I and Statement-II are correct and Statement-II is not the correct explanation for Statement-I", "body_hi": "कथन-I और कथन-II दोनों सही हैं, किंतु कथन-II, कथन-I की सही व्याख्या नहीं है", "isCorrect": true}, {"id": "c", "body": "Statement-I is correct but Statement-II is incorrect", "body_hi": "कथन-I सही है, किंतु कथन-II गलत है", "isCorrect": false}, {"id": "d", "body": "Statement-I is incorrect but Statement-II is correct", "body_hi": "कथन-I गलत है, किंतु कथन-II सही है", "isCorrect": false}]'::jsonb,2,0.66,'Both statements are correct, but Statement-II does not explain Statement-I. Money supply rises because the RBI pays for the dollars with newly created rupees; sterilisation describes what the RBI may do afterwards to mop up those rupees -- selling bonds in open market operations or, when needed, issuing bonds under the Market Stabilisation Scheme. It is a response to the effect, not its cause.','दोनों कथन सही हैं, पर कथन-II कथन-I की व्याख्या नहीं करता। मुद्रा आपूर्ति इसलिए बढ़ती है कि RBI डॉलरों का भुगतान नए सृजित रुपयों से करता है; निष्फलीकरण बताता है कि RBI बाद में उन रुपयों को सोखने के लिए क्या कर सकता है, जैसे खुले बाज़ार की क्रियाओं में बॉन्ड बेचना या आवश्यकता पड़ने पर बाज़ार स्थिरीकरण योजना के तहत बॉन्ड जारी करना। यह प्रभाव की प्रतिक्रिया है, उसका कारण नहीं।','econ-forex-intervention-sterilisation','original_pattern_matched','Reserve Bank of India -- Market Stabilisation Scheme; Annual Report.','draft'),
('upsc','Economy','Money, Banking & Monetary Policy','match_the_following','medium','Consider the following pairs of institutions and their main functions:','संस्थाओं और उनके मुख्य कार्यों के निम्नलिखित युग्मों पर विचार कीजिए:','{"list_1": ["1. NABARD", "2. SIDBI", "3. EXIM Bank", "4. National Housing Bank"], "list_1_hi": ["1. नाबार्ड", "2. सिडबी", "3. एक्ज़िम बैंक", "4. राष्ट्रीय आवास बैंक"], "list_2": ["Agriculture and rural credit", "Finance for micro, small and medium enterprises", "Finance for foreign trade", "Refinance for housing finance companies"], "list_2_hi": ["कृषि और ग्रामीण ऋण", "सूक्ष्म, लघु और मध्यम उद्यमों के लिए वित्त", "विदेशी व्यापार के लिए वित्त", "आवास वित्त कंपनियों के लिए पुनर्वित्त"], "closing": "How many of the pairs given above are correctly matched?", "closing_hi": "उपर्युक्त में से कितने युग्म सही सुमेलित हैं?", "fixed_option_order": true}'::jsonb,'[{"id": "a", "body": "Only one pair", "body_hi": "केवल एक युग्म", "isCorrect": false}, {"id": "b", "body": "Only two pairs", "body_hi": "केवल दो युग्म", "isCorrect": false}, {"id": "c", "body": "Only three pairs", "body_hi": "केवल तीन युग्म", "isCorrect": false}, {"id": "d", "body": "All four pairs", "body_hi": "सभी चार युग्म", "isCorrect": true}]'::jsonb,2,0.66,'All four pairs are correct. These are the all-India financial institutions regulated by the RBI: NABARD (1982) refinances rural credit and supervises regional rural and cooperative banks; SIDBI (1990) serves small industry and also runs MUDRA; the EXIM Bank (1982) finances exports and imports; and the National Housing Bank (1988) refinances housing finance companies and supervises them, although their regulation passed to the RBI in 2019. A student who expects one mismatch will fall for ''Only three pairs''.','चारों युग्म सही हैं। ये RBI द्वारा विनियमित अखिल भारतीय वित्तीय संस्थाएँ हैं: नाबार्ड (1982) ग्रामीण ऋण का पुनर्वित्त करता है और क्षेत्रीय ग्रामीण तथा सहकारी बैंकों की निगरानी करता है; सिडबी (1990) लघु उद्योग को सेवा देता है और मुद्रा (MUDRA) भी चलाता है; एक्ज़िम बैंक (1982) निर्यात और आयात का वित्तपोषण करता है; और राष्ट्रीय आवास बैंक (1988) आवास वित्त कंपनियों का पुनर्वित्त और निगरानी करता है, यद्यपि उनका विनियमन 2019 में RBI के पास चला गया। जो विद्यार्थी एक बेमेल की अपेक्षा करता है, वह ''केवल तीन युग्म'' के जाल में फँसेगा।','econ-dfi-functions-pairs','original_pattern_matched','Reserve Bank of India -- All India Financial Institutions.','draft')
